//! A Frame made by picking axes out of a SkyFrame, checked against the C
//! library.
//!
//! C's SubFrame attaches the picked SkyAxis objects to a plain Frame, after
//! setting on them the attributes whose defaults the SkyFrame class
//! supplies, so the picked axes keep formatting, unformatting, normalising
//! and dumping as a SkyAxis does. `picked_skyaxis_oracle/cases.rs` is
//! generated by `tools/oracle_fixtures/picked_skyaxis_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "picked_skyaxis_oracle/cases.rs"]
mod cases;

use cases::V;

use ast_core::frames::{BasicFrame, DynFrame, Frame, SkyFrame, SkyRefIs, SkySystem, pick_axes};
use ast_core::{AnyObject, from_native_string, to_native_string};

/// A default SkyFrame with each `;`-separated setting applied in turn, as
/// the probe applies them.
fn sky_frame(settings: &str) -> SkyFrame {
    let mut f = SkyFrame::unset_system();
    for setting in settings.split(';').filter(|s| !s.is_empty()) {
        if setting == "PERM" {
            f.perm_axes(&[2, 1]).unwrap();
            continue;
        }
        let (name, value) = setting.split_once('=').unwrap();
        let (name, axis) = match name.split_once('(') {
            Some((n, rest)) => (n, rest.trim_end_matches(')').parse().unwrap()),
            None => (name, 0),
        };
        match (name, axis) {
            ("System", _) => f.set_system(SkySystem::parse(value).unwrap()),
            ("NegLon", _) => f.set_neglon(value != "0"),
            ("Digits", 0) => Frame::set_digits(&mut f, value.parse().unwrap()).unwrap(),
            ("Digits", a) => f.set_axis_digits(a, value.parse().unwrap()).unwrap(),
            ("Format", a) => f.set_format_str(a, value).unwrap(),
            ("AsTime", a) => f.set_as_time(a, value != "0").unwrap(),
            ("Unit", a) => f.set_unit(a, value).unwrap(),
            ("Label", a) => f.set_label(a, value).unwrap(),
            ("Symbol", a) => f.set_symbol(a, value).unwrap(),
            ("SkyRef", a) => f.set_sky_ref(a, value.parse().unwrap()).unwrap(),
            ("SkyRefIs", _) => f.set_sky_ref_is(SkyRefIs::parse(value).unwrap()),
            (other, _) => panic!("unexpected setting {other}"),
        }
    }
    f
}

fn picked(settings: &str, pick: &str) -> DynFrame {
    let axes: Vec<usize> = pick.split(',').map(|a| a.parse().unwrap()).collect();
    pick_axes(&sky_frame(settings), &axes).unwrap().0
}

fn query(f: &dyn Frame, q: &str, axis: usize, second: bool) -> V {
    let s = |v: String| V::S(Box::leak(v.into_boxed_str()));
    if let Some(v) = q.strip_prefix("Format:") {
        return s(f.format(axis, v.parse().unwrap()).unwrap());
    }
    if let Some(args) = q.strip_prefix("AxOffset:") {
        let (v1, d) = args.split_once(',').unwrap();
        return V::D(
            f.ax_offset(axis, v1.parse().unwrap(), d.parse().unwrap())
                .unwrap(),
        );
    }
    if let Some(args) = q.strip_prefix("AxDistance:") {
        let (v1, v2) = args.split_once(',').unwrap();
        return V::D(
            f.ax_distance(axis, v1.parse().unwrap(), v2.parse().unwrap())
                .unwrap(),
        );
    }
    if let Some(text) = q.strip_prefix("Unformat:") {
        // C reports a value of 0 when nothing is read.
        let (v, n) = f.unformat(axis, text).unwrap();
        return if second {
            V::I(n as i32)
        } else if n == 0 {
            V::D(0.0)
        } else {
            V::D(v)
        };
    }
    match q {
        "Domain" => s(f.domain().to_string()),
        "Title" => s(f.title()),
        "Label" => s(f.label(axis).unwrap()),
        "Symbol" => s(f.symbol(axis).unwrap()),
        "Unit" => s(f.unit(axis).unwrap()),
        "Format" => s(f.format_str(axis).unwrap()),
        "Digits" => V::I(f.axis_digits(axis).unwrap()),
        "Direction" => V::I(i32::from(f.direction(axis).unwrap())),
        "Top" => V::D(f.top(axis).unwrap()),
        "Bottom" => V::D(f.bottom(axis).unwrap()),
        "NormUnit" => s(f.norm_unit(axis)),
        other => panic!("unexpected query {other}"),
    }
}

#[test]
fn every_value_matches_the_c_library() {
    let mut failures = Vec::new();
    let mut last: Option<(&str, &str, DynFrame)> = None;
    let mut previous: Option<(&str, &str, &str, usize)> = None;
    for &(setting, pick, q, axis, expected) in cases::CASES {
        if last
            .as_ref()
            .is_none_or(|(s, p, _)| (*s, *p) != (setting, pick))
        {
            last = Some((setting, pick, picked(setting, pick)));
        }
        let f = last.as_ref().unwrap().2.as_ref();
        // An Unformat query has two rows, the value and then the count.
        let second = previous == Some((setting, pick, q, axis));
        previous = Some((setting, pick, q, axis));
        let got = query(f, q, axis, second);
        if got != expected {
            failures.push(format!(
                "{setting:?} pick {pick} {q}({axis}): got {got:?}, C gives {expected:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ:\n{}",
        failures.len(),
        cases::CASES.len(),
        failures.join("\n")
    );
}

fn native(f: &dyn Frame) -> String {
    let any = f.as_any();
    let obj = if let Some(b) = any.downcast_ref::<BasicFrame>() {
        AnyObject::BasicFrame(b.clone())
    } else {
        AnyObject::SkyFrame(any.downcast_ref::<SkyFrame>().unwrap().clone())
    };
    to_native_string(&obj).unwrap()
}

/// The picked Frame dumps as C's does, and C's dump reads back to a Frame
/// that writes it again.
#[test]
fn dump_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(setting, pick, expected) in cases::DUMP_CASES {
        let written = native(picked(setting, pick).as_ref());
        if written != expected {
            failures.push(format!(
                "dump for {setting:?} pick {pick}:\n--- port\n{written}--- C\n{expected}"
            ));
            continue;
        }
        let read = from_native_string(expected).unwrap();
        let rewritten = to_native_string(&read).unwrap();
        if rewritten != expected {
            failures.push(format!(
                "round trip of C's dump for {setting:?} pick {pick}:\n--- port\n{rewritten}--- C\n{expected}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} dumps differ:\n{}",
        failures.len(),
        cases::DUMP_CASES.len(),
        failures.join("\n")
    );
}
